    // ── Serve readiness payload (#1639) ────────────────────────────────────
    //
    // The supervisor reads the drain budget and the bound address from this file.
    // The address lets `autumn serve --daemon` write a discovery file on a platform
    // with no Unix socket to name in advance.

    #[test]
    fn a_wildcard_bind_is_published_as_a_dialable_loopback_address() {
        // Production binds `0.0.0.0` by default. Publishing that would hand a thin
        // client an address nothing can dial after a start that reported success.
        assert_eq!(dialable_endpoint("0.0.0.0:3000"), "127.0.0.1:3000");
        assert_eq!(dialable_endpoint("[::]:3000"), "[::1]:3000");
    }

    #[test]
    fn a_specific_bind_is_published_exactly_as_bound() {
        // Rewriting a specific bind would advertise an interface the app is not on.
        assert_eq!(dialable_endpoint("192.168.1.10:3000"), "192.168.1.10:3000");
        assert_eq!(dialable_endpoint("127.0.0.1:8080"), "127.0.0.1:8080");
        assert_eq!(dialable_endpoint("[::1]:8080"), "[::1]:8080");
    }

    #[test]
    fn the_resolved_port_survives_the_rewrite() {
        // `port = 0` resolves in the kernel, so the supervisor cannot know the port itself.
        assert_eq!(dialable_endpoint("0.0.0.0:49152"), "127.0.0.1:49152");
    }

    #[test]
    fn an_unparseable_address_is_published_unchanged() {
        // Better to publish what was bound than to invent something.
        assert_eq!(dialable_endpoint("not-an-address"), "not-an-address");
    }

    #[test]
    fn serve_ready_payload_leads_with_the_drain_budget() {
        // Line one stays a bare integer so a supervisor that predates the
        // address line still reads the budget it always read.
        let payload = serve_ready_payload(35, "tcp 127.0.0.1:3000");
        assert_eq!(payload.lines().next(), Some("35"));
    }

    #[test]
    fn serve_ready_payload_carries_the_bound_endpoint_on_line_two() {
        let payload = serve_ready_payload(35, "tcp 127.0.0.1:3000");
        assert_eq!(payload.lines().nth(1), Some("tcp 127.0.0.1:3000"));
    }

    #[test]
    fn serve_ready_payload_survives_a_socket_path_containing_spaces() {
        // A Unix socket under a directory with a space is legal, so the format
        // has to split on the FIRST separator only, never on every one.
        let payload = serve_ready_payload(1, "unix /home/a b/serve.sock");
        let line = payload.lines().nth(1).expect("endpoint line");
        assert_eq!(line.split_once(' '), Some(("unix", "/home/a b/serve.sock")));
    }

    #[test]
    fn serve_ready_payload_never_emits_a_bare_newline_for_an_unknown_endpoint() {
        // An empty endpoint must not leave a blank line a reader could mistake
        // for an address. The capability line fills line two.
        let payload = serve_ready_payload(7, "");
        assert!(payload.lines().all(|l| !l.trim().is_empty()), "{payload:?}");
        assert_eq!(
            payload.lines().nth(1),
            Some(SHUTDOWN_SIGNAL_CAPABILITY_LINE)
        );
    }

    #[test]
    fn serve_ready_payload_advertises_the_shutdown_signal_capability() {
        for endpoint in ["tcp 127.0.0.1:3000", ""] {
            let payload = serve_ready_payload(35, endpoint);
            assert!(
                serve_ready_advertises_shutdown_signal(&payload),
                "{payload:?}"
            );
        }
    }

    #[test]
    fn the_capability_line_never_displaces_the_endpoint_line() {
        let payload = serve_ready_payload(35, "tcp 127.0.0.1:3000");
        assert_eq!(payload.lines().nth(1), Some("tcp 127.0.0.1:3000"));
    }

    #[test]
    fn a_budget_only_ready_file_does_not_advertise_the_capability() {
        // An app that predates the signal protocol still wrote this much.
        for old in ["35", "35\n", "35\ntcp 127.0.0.1:3000", ""] {
            assert!(!serve_ready_advertises_shutdown_signal(old), "{old:?}");
        }
    }

    #[test]
    fn an_unrelated_capability_is_not_the_shutdown_signal() {
        assert!(!serve_ready_advertises_shutdown_signal(
            "35\ncapability other"
        ));
    }

    // ── Cooperative external shutdown (#1616) ──────────────────────────────
    //
    // Windows has no SIGTERM, and `TerminateProcess` skips `on_shutdown` hooks, which
    // orphaned a managed Postgres child on every `autumn dev` reload. An opt-in,
    // env-named flag file drains the app through the same graceful path a signal takes.

    #[test]
    fn external_shutdown_path_is_none_when_the_env_var_is_absent() {
        assert_eq!(external_shutdown_path_from(None), None);
    }

    #[test]
    fn external_shutdown_path_ignores_an_empty_env_value() {
        // An empty value is what an unset-but-exported variable looks like. It
        // must not resolve to the current directory, where any stray file would
        // drain the app.
        assert_eq!(
            external_shutdown_path_from(Some(std::ffi::OsStr::new(""))),
            None
        );
        assert_eq!(
            external_shutdown_path_from(Some(std::ffi::OsStr::new("   "))),
            None
        );
    }

    #[test]
    fn external_shutdown_path_trims_surrounding_whitespace() {
        // A path with a leading space never matches the file the parent writes, so on
        // Windows every reload would silently stall the full budget and hard-kill.
        assert_eq!(
            external_shutdown_path_from(Some(std::ffi::OsStr::new("  /tmp/autumn-stop  "))),
            Some(std::path::PathBuf::from("/tmp/autumn-stop"))
        );
    }

    #[tokio::test]
    async fn external_shutdown_signal_ignores_a_directory_at_the_path() {
        // `metadata()` succeeds on a directory. If existence alone were the
        // test, pointing the variable at a directory would drain the app on
        // every boot — bind, drain, exit 0 — which under a supervisor is a
        // restart loop that reports success on every iteration.
        let tmp = tempfile::TempDir::new().unwrap();
        let path = tmp.path().join("not-a-signal");
        std::fs::create_dir(&path).unwrap();

        let resolved = tokio::time::timeout(
            std::time::Duration::from_millis(400),
            external_shutdown_signal(Some(path)),
        )
        .await;
        assert!(resolved.is_err(), "a directory must not count as a signal");
    }

    #[test]
    fn external_shutdown_path_uses_the_env_value_verbatim() {
        assert_eq!(
            external_shutdown_path_from(Some(std::ffi::OsStr::new("/tmp/autumn-stop"))),
            Some(std::path::PathBuf::from("/tmp/autumn-stop"))
        );
    }

    #[tokio::test]
    async fn external_shutdown_signal_never_resolves_without_a_path() {
        // Not configured must mean "never drains" — not "drains immediately",
        // which would take down every app that does not opt in.
        let pending = tokio::time::timeout(
            std::time::Duration::from_millis(300),
            external_shutdown_signal(None),
        )
        .await;
        assert!(
            pending.is_err(),
            "an unconfigured signal must never resolve"
        );
    }

    #[tokio::test]
    async fn external_shutdown_signal_resolves_when_the_file_appears() {
        let tmp = tempfile::TempDir::new().unwrap();
        let path = tmp.path().join("dev-shutdown.signal");

        let writer_path = path.clone();
        let writer = tokio::spawn(async move {
            tokio::time::sleep(std::time::Duration::from_millis(150)).await;
            std::fs::write(&writer_path, b"stop").unwrap();
        });

        let signalled = tokio::time::timeout(
            std::time::Duration::from_secs(5),
            external_shutdown_signal(Some(path)),
        )
        .await;
        assert!(signalled.is_ok(), "writing the file must drain the app");
        writer.await.unwrap();
    }

    #[tokio::test]
    async fn external_shutdown_signal_resolves_immediately_when_present_at_boot() {
        // `autumn dev` removes a stale file before spawning, but a crashed
        // parent can leave one behind; resolving immediately is the safe
        // direction — the app exits gracefully rather than ignoring a stop.
        let tmp = tempfile::TempDir::new().unwrap();
        let path = tmp.path().join("dev-shutdown.signal");
        std::fs::write(&path, b"stop").unwrap();

        let signalled = tokio::time::timeout(
            std::time::Duration::from_secs(5),
            external_shutdown_signal(Some(path)),
        )
        .await;
        assert!(
            signalled.is_ok(),
            "a file present at boot must drain the app"
        );
    }

    #[test]
    fn external_shutdown_env_var_is_the_name_the_cli_writes() {
        // `autumn-cli` mirrors this constant; a rename on either side silently breaks
        // the dev loop.
        assert_eq!(SHUTDOWN_SIGNAL_FILE_ENV, "AUTUMN_SHUTDOWN_SIGNAL_FILE");
    }

    #[tokio::test]
    async fn canary_rollback_signal_resolves_when_flag_newly_written() {
        let tmp = tempfile::TempDir::new().unwrap();
        let path = tmp.path().join("canary-rollback.json");

        let writer_path = path.clone();
        let writer = tokio::spawn(async move {
            tokio::time::sleep(std::time::Duration::from_millis(150)).await;
            crate::canary::CanaryState::write_rollback_flag(
                &writer_path,
                &crate::canary::RollbackSignal::default(),
            )
            .unwrap();
        });

        let signalled = tokio::time::timeout(
            std::time::Duration::from_secs(5),
            canary_rollback_signal(&path),
        )
        .await;
        assert!(signalled.is_ok(), "rollback signal should resolve");
        writer.await.unwrap();
    }

    #[tokio::test]
    async fn canary_rollback_signal_resolves_immediately_when_flag_present_at_boot() {
        let tmp = tempfile::TempDir::new().unwrap();
        let path = tmp.path().join("canary-rollback.json");
        // A rollback flag is sticky across restarts: present at boot must trigger
        // again so a supervisor restart cannot rejoin a rolled-back replica.
        crate::canary::CanaryState::write_rollback_flag(
            &path,
            &crate::canary::RollbackSignal::default(),
        )
        .unwrap();

        let signalled = tokio::time::timeout(
            std::time::Duration::from_secs(5),
            canary_rollback_signal(&path),
        )
        .await;
        assert!(
            signalled.is_ok(),
            "a flag present at boot must trigger rollback (sticky across restarts)"
        );
    }

    // Postgres only: SQLite refuses a distinct `replica_url` at config validation and at
    // topology build. Gated rather than rewritten, so no test asserts a refused config.
    #[cfg(not(feature = "sqlite"))]
    #[cfg(feature = "db")]
    #[test]
    fn build_state_applies_replica_fallback_policy_to_read_routing() {
        let mut config = AutumnConfig::default();
        config.database.primary_url = Some("postgres://localhost/primary".to_owned());
        config.database.primary_pool_size = Some(5);
        config.database.replica_url = Some("postgres://localhost/replica".to_owned());
        config.database.replica_pool_size = Some(2);
        config.database.replica_fallback = crate::config::ReplicaFallback::Primary;
        let topology = crate::db::create_topology(&config.database)
            .expect("topology should build")
            .expect("database should be configured");

        let state = build_state(
            &config,
            Some(&topology),
            None,
            #[cfg(feature = "ws")]
            None,
        );
        state
            .probes()
            .mark_replica_unready("replica migrations lag primary");

        assert_eq!(state.read_pool().expect("read pool").status().max_size, 5);
    }

    #[test]
    fn build_state_exposes_resolved_process_role() {
        use crate::config::ProcessRole;

        // The default is the combined role: HTTP and workers in one process.
        let mut config = AutumnConfig::default();
        let state = build_state(
            &config,
            #[cfg(feature = "db")]
            None,
            #[cfg(feature = "db")]
            None,
            #[cfg(feature = "ws")]
            None,
        );
        assert_eq!(state.role().base(), ProcessRole::Combined);
        assert_eq!(state.role().name(), "combined");
        assert_eq!(state.capabilities(), ProcessRole::Combined.capabilities());

        // `state.role()` goes through the same resolution that gates the job runtime.
        config.role = ProcessRole::Worker.into();
        let state = build_state(
            &config,
            #[cfg(feature = "db")]
            None,
            #[cfg(feature = "db")]
            None,
            #[cfg(feature = "ws")]
            None,
        );
        assert_eq!(state.role().base(), ProcessRole::Worker);
        assert_eq!(
            state.capabilities(),
            config.resolve_role().expect("worker").capabilities()
        );
        assert!(state.capabilities().job_workers);
        assert!(!state.capabilities().serves_http);
    }

    /// A config with `[roles.<name>]` presets and the given role and jobs backend.
    fn named_role_config_3543(role: &str, backend: &str) -> AutumnConfig {
        let toml = format!(
            "role = \"{role}\"\n[jobs]\nbackend = \"{backend}\"\n\
             [roles.critical]\nbase = \"worker\"\npin = [\"critical\"]\nscheduler = false\n\
             [roles.api]\nbase = \"web\"\n\
             [roles.marketing]\nbase = \"combined\"\n"
        );
        toml::from_str(&toml).expect("named role config")
    }

    #[test]
    fn build_state_exposes_named_role() {
        let config = named_role_config_3543("critical", "postgres");
        let state = build_state(
            &config,
            #[cfg(feature = "db")]
            None,
            #[cfg(feature = "db")]
            None,
            #[cfg(feature = "ws")]
            None,
        );
        assert_eq!(state.role().name(), "critical");
        assert_eq!(state.role().base(), crate::config::ProcessRole::Worker);
        assert!(state.capabilities().job_workers);
        assert!(!state.capabilities().scheduler);
        assert!(!state.capabilities().serves_http);
    }

    /// The durable-backend guard reads the base of a named role.
    #[test]
    fn durable_backend_guard_fires_for_named_split_roles_on_local() {
        for role in ["critical", "api"] {
            let config = named_role_config_3543(role, "local");
            let err = validate_config_preconditions(&config, &[])
                .expect_err("a named web/worker role on local must not boot");
            assert!(err.contains(role), "{role}: {err}");
            assert!(err.contains("durable jobs backend"), "{role}: {err}");
            for backend in ["postgres", "redis", "sqlite"] {
                let config = named_role_config_3543(role, backend);
                validate_config_preconditions(&config, &[])
                    .unwrap_or_else(|err| panic!("{role} on {backend}: {err}"));
            }
        }
        // A combined base enqueues and drains in one process.
        let config = named_role_config_3543("marketing", "local");
        validate_config_preconditions(&config, &[]).expect("combined base on local");
    }

    /// A `combined` preset with no job workers counts as split: it enqueues
    /// into a queue that it does not drain.
    #[test]
    fn durable_backend_guard_fires_for_a_non_draining_combined_preset() {
        for body in ["job_workers = false", "pin = []"] {
            let toml = format!(
                "role = \"api\"\n[jobs]\nbackend = \"local\"\n[roles.api]\nbase = \"combined\"\n{body}\n"
            );
            let config: AutumnConfig = toml::from_str(&toml).expect("config");
            let err = validate_config_preconditions(&config, &[]).expect_err(body);
            assert!(err.contains("api (base combined)"), "{body}: {err}");
        }
    }

    /// The job runtime gets the preset `pin` and `workers`.
    #[test]
    fn role_job_config_applies_the_preset() {
        let config = named_role_config_3543("critical", "postgres");
        let role = config.resolve_role().expect("critical");
        let mut jobs = config.jobs;
        jobs.pin = vec!["bulk".to_owned()];
        assert_eq!(
            role_job_config(&role, &jobs).pin,
            vec!["critical".to_owned()]
        );
        let builtin = crate::config::Role::from(crate::config::ProcessRole::Worker);
        assert_eq!(
            role_job_config(&builtin, &jobs).pin,
            vec!["bulk".to_owned()]
        );

        // The server boot passes that config to the job runtime.
        let source = include_str!("app.rs").replace("\r\n", "\n");
        let boot = "let role_jobs = role_job_config(state.role(), &config.jobs);\n        \
                    if let Err(error) = initialize_job_runtime(\n            jobs,\n            \
                    &state,\n            &server_shutdown,\n            &role_jobs,";
        assert!(
            source.contains(boot),
            "the server boot must pass the preset job config"
        );
    }

    /// The file-backed `SQLite` guard reads the base of a named role.
