    #[cfg(feature = "i18n")]
    #[tokio::test]
    #[allow(
        clippy::await_holding_lock,
        reason = "the guard must span the `load_config_and_telemetry` await — that \
                  await is what mutates the limits, so dropping the lock before it \
                  would serialize nothing. Same shape, and the same reason, as \
                  `config_runtime_drift_actuator_prefix_is_mounted`'s circuit-breaker \
                  guard: the contending holders are sibling libtest threads, not \
                  tasks on this runtime, so blocking here cannot starve the future \
                  that would release it."
    )]
    async fn i18n_auto_uses_config_loader_output_for_bundle_dir() {
        // `load_config_and_telemetry` resets the process-global metric limits. Hold the
        // metrics tests' lock so this cannot land inside a test that raised a cap.
        // See `metrics::LIMITS_TEST_LOCK`.
        let _limits_lock = crate::metrics::LIMITS_TEST_LOCK
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);

        let project = tempfile::tempdir().expect("project dir");
        let i18n_dir = project.path().join("custom-i18n");
        std::fs::create_dir_all(&i18n_dir).expect("i18n dir");
        std::fs::write(i18n_dir.join("en.ftl"), "nav.home = Loader Home\n").expect("bundle");

        let mut config = AutumnConfig::default();
        config.i18n.dir = "custom-i18n".to_owned();
        let builder = app()
            .with_config_loader(StaticConfigLoader { config })
            .with_telemetry_provider(NoopTelemetryProvider)
            .i18n_auto();
        let AppBuilder {
            config_loader_factory,
            telemetry_provider,
            i18n_bundle,
            i18n_auto_load,
            plugin_config_roots,
            ..
        } = builder;

        let (loaded_config, _guard) = load_config_and_telemetry(
            config_loader_factory,
            telemetry_provider,
            plugin_config_roots,
        )
        .await;
        let env = crate::config::MockEnv::new().with(
            "AUTUMN_MANIFEST_DIR",
            project.path().to_str().expect("utf-8 path"),
        );
        let bundle = resolve_i18n_bundle(i18n_bundle, i18n_auto_load, &loaded_config, &env)
            .expect("bundle loaded from configured dir");

        assert_eq!(bundle.translate("en", "nav.home", &[]), "Loader Home");
    }

    /// #1384: `locale_prefix_enabled` is supported WITHOUT `.i18n()` /
    /// `.i18n_auto()` — the router builds its `/{locale}` nests straight from
    /// `I18nConfig` — so no `Bundle` exists in that shape. Column decoding
    /// still needs the app's default locale: without it a `default_locale =
    /// "fr"` app attributes every legacy plain-text value to the last-resort
    /// `"en"`, so a `/fr/...` request renders upgraded content as empty and a
    /// later write can persist it under the wrong locale.
    #[cfg(feature = "i18n")]
    #[test]
    fn locale_defaults_are_installed_even_with_no_bundle() {
        let mut config = AutumnConfig::default();
        config.i18n.default_locale = "fr".to_owned();
        config.i18n.supported_locales = vec!["fr".to_owned(), "en".to_owned()];
        let state = AppState::for_test();

        let layers = install_i18n_bundle_layer(Vec::new(), &state, None, &config.i18n);

        assert!(
            layers.is_empty(),
            "no bundle means no Extension and no ambient layer registration"
        );
        assert_eq!(
            &*crate::i18n::default_locale_snapshot(),
            "fr",
            "the configured default must reach column decoding without a bundle"
        );
        // A legacy plain-text column is attributed to `fr`, so a `/fr/...` request
        // resolves it instead of rendering empty.
        let legacy = crate::i18n::Translated::decode_column(
            "Bonjour le monde",
            &crate::i18n::default_locale_snapshot(),
        );
        assert_eq!(legacy.get("fr"), Some("Bonjour le monde"));

        // Restore the framework default for the rest of this binary.
        crate::i18n::install_locale_defaults("en", vec!["en".to_owned()]);
    }

    /// #1384: drive the REAL wiring — `install_i18n_bundle_layer` +
    /// `try_build_router_inner` — and assert both the ambient locale and a
    /// `Translated` field resolve for a handler that takes NO locale argument.
    ///
    /// This pins the layer-ORDERING invariant the feature rests on: the bundle
    /// `Extension` must be registered first (outermost) so the ambient layer,
    /// registered second, can read it while negotiating. Swap the two pushes
    /// and the layer negotiates against an empty supported-list, pins every
    /// request to the default locale, and this test goes red — where a
    /// hand-built router stack would not notice.
    #[cfg(feature = "i18n")]
    #[tokio::test]
    async fn ambient_locale_layer_resolves_translatable_content_through_the_real_stack() {
        use tower::ServiceExt as _;

        async fn show() -> String {
            let title =
                crate::i18n::Translated::from_pairs([("en", "Hello world"), ("es", "Hola mundo")]);
            // No `Locale` parameter anywhere in this signature.
            format!(
                "{}|{}",
                title,
                crate::i18n::ambient_locale().unwrap_or_default()
            )
        }

        let mut config = AutumnConfig::default();
        config.i18n.supported_locales = vec!["en".to_owned(), "es".to_owned()];
        let bundle = Arc::new(crate::i18n::Bundle::from_messages(
            std::collections::HashMap::new(),
            &config.i18n,
        ));
        let state = AppState::for_test();
        let custom_layers =
            install_i18n_bundle_layer(Vec::new(), &state, Some(bundle), &config.i18n);

        let router = crate::router::try_build_router_inner(
            vec![Route {
                method: http::Method::GET,
                path: "/show",
                handler: axum::routing::get(show),
                name: "show",
                api_doc: crate::openapi::ApiDoc {
                    method: "GET",
                    path: "/show",
                    operation_id: "show",
                    success_status: 200,
                    ..Default::default()
                },
                repository: None,
                idempotency: crate::route::RouteIdempotency::Direct,
                timeout: crate::route::RouteTimeout::Inherit,
                criticality: crate::admission::Criticality::Default,
                seo: crate::seo::SeoRouteDefaults::EMPTY,
                api_version: None,
                sunset_opt_out: false,
                group: None,
            }],
            &config,
            state,
            crate::router::RouterContext {
                exception_filters: Vec::new(),
                scoped_groups: Vec::new(),
                merge_routers: Vec::new(),
                nest_routers: Vec::new(),
                declared_routes: Vec::new(),
                custom_layers,
                static_gate_layers: Vec::new(),
                #[cfg(feature = "maud")]
                error_page_renderer: None,
                session_store: None,
                #[cfg(feature = "openapi")]
                openapi: None,
                #[cfg(feature = "mcp")]
                mcp: None,
                #[cfg(feature = "webmcp")]
                webmcp: None,
            },
        )
        .expect("router builds");

        for (accept_language, expected) in [
            ("es", "Hola mundo|es"),
            // Untranslated: falls back through the configured chain to `en`.
            ("fr", "Hello world|en"),
        ] {
            let request = axum::http::Request::builder()
                .uri("/show")
                .header(http::header::ACCEPT_LANGUAGE, accept_language)
                .body(axum::body::Body::empty())
                .expect("request");
            let response = router.clone().oneshot(request).await.expect("response");
            let bytes = axum::body::to_bytes(response.into_body(), 4096)
                .await
                .expect("body");
            assert_eq!(
                String::from_utf8(bytes.to_vec()).expect("utf-8"),
                expected,
                "Accept-Language: {accept_language}"
            );
        }
    }

    // ── The origin never leaks the edge fallthrough sentinel (#2244) ──────
    //
    // `EdgeCacheUnavailable` sets the fallthrough sentinel header so the edge runtime
    // falls through to the origin. The same extractor runs at the origin, so an app that
    // never calls `with_edge_kv` hits this 500 there, and a real client must not see
    // the internal header.
    #[cfg(feature = "edge")]
    #[tokio::test]
    async fn an_uninjected_edge_seam_never_leaks_the_fallthrough_sentinel_to_a_real_client() {
        async fn note(_cache: autumn_edge::EdgeCache) -> &'static str {
            "never reached: extraction fails first"
        }

        // `with_edge_kv` is never called.
        let custom_layers = app().custom_layers;

        let router = crate::router::try_build_router_inner(
            vec![Route {
                method: http::Method::GET,
                path: "/edge/note",
                handler: axum::routing::get(note),
                name: "note",
                api_doc: crate::openapi::ApiDoc {
                    method: "GET",
                    path: "/edge/note",
                    operation_id: "note",
                    success_status: 200,
                    ..Default::default()
                },
                repository: None,
                idempotency: crate::route::RouteIdempotency::Direct,
                timeout: crate::route::RouteTimeout::Inherit,
                criticality: crate::admission::Criticality::Default,
                seo: crate::seo::SeoRouteDefaults::EMPTY,
                api_version: None,
                sunset_opt_out: false,
                group: None,
            }],
            &AutumnConfig::default(),
            AppState::for_test(),
            crate::router::RouterContext {
                exception_filters: Vec::new(),
                scoped_groups: Vec::new(),
                merge_routers: Vec::new(),
                nest_routers: Vec::new(),
                declared_routes: Vec::new(),
                custom_layers,
                static_gate_layers: Vec::new(),
                #[cfg(feature = "maud")]
                error_page_renderer: None,
                session_store: None,
                #[cfg(feature = "openapi")]
                openapi: None,
                #[cfg(feature = "mcp")]
                mcp: None,
                #[cfg(feature = "webmcp")]
                webmcp: None,
            },
        )
        .expect("router builds");

        let request = axum::http::Request::builder()
            .uri("/edge/note")
            .body(axum::body::Body::empty())
            .expect("request");
        let response = router.oneshot(request).await.expect("response");

        assert_eq!(response.status(), StatusCode::INTERNAL_SERVER_ERROR);
        assert!(
            !response
                .headers()
                .contains_key(autumn_edge::FALLTHROUGH_SENTINEL),
            "the origin must strip the internal fallthrough sentinel: {:?}",
            response.headers()
        );

        let body = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("body");
        let body = String::from_utf8_lossy(&body);
        assert!(
            body.contains("with_edge_kv"),
            "the actionable message must survive: {body}"
        );
    }

    /// `app()` registers the sentinel-strip layer through the ordinary
    /// `AppBuilder::layer` path, which the idempotency machinery otherwise
    /// treats as "opaque" (forcing fail-closed replay) for any custom layer
    /// it does not specifically recognize — see
    /// `router::is_idempotency_transparent_app_layer`. Without that
    /// recognition, every app built with the `edge` feature on would force
    /// fail-closed idempotency, whether or not it ever calls `with_edge_kv`.
    /// This pins the real registration's `type_name` against the substring
    /// that recognizer matches on, so the two sides cannot drift apart.
    #[cfg(feature = "edge")]
    #[test]
    fn the_sentinel_strip_layer_is_recognized_as_idempotency_transparent() {
        let registration = &app().custom_layers[0];
        assert_eq!(
            registration.type_id,
            std::any::TypeId::of::<StripEdgeFallthroughSentinelLayer>(),
            "the real registration's type_id no longer matches what \
             router::is_idempotency_transparent_app_layer looks for"
        );
    }

    /// `get_layer_types()` documents "only user-installed layers", but the
    /// sentinel-strip layer above shares its underlying storage
    /// (`custom_layers`) with real `AppBuilder::layer` calls so the
    /// router-build step applies both the same way. Without filtering it
    /// back out, a plugin (or a test like
    /// `middleware_introspection::get_layer_types_returns_registration_order`)
    /// asserting an exact layer list sees this internal registration leak in
    /// as an unexpected leading entry (Codex review on #2739, round 6, P1).
    #[cfg(feature = "edge")]
    #[test]
    fn get_layer_types_excludes_the_framework_owned_sentinel_strip_layer() {
        #[derive(Clone, Copy)]
        struct UserLayer;
        impl<S> tower::Layer<S> for UserLayer {
            type Service = S;
            fn layer(&self, inner: S) -> S {
                inner
            }
        }

        let builder = app().layer(UserLayer);
        assert_eq!(
            builder.get_layer_types(),
            vec![std::any::TypeId::of::<UserLayer>()],
            "the framework's own sentinel-strip registration must not appear \
             in the user-facing layer list"
        );
    }

    /// The header-stripping behavior itself, independent of the router-level
    /// idempotency classification test above.
    #[cfg(feature = "edge")]
    #[tokio::test]
    async fn the_sentinel_strip_service_removes_the_header_and_keeps_the_body() {
        use axum::response::IntoResponse as _;
        use tower::{Layer as _, Service as _, ServiceExt as _};

        let inner = tower::service_fn(|_req: axum::extract::Request| async move {
            Ok::<_, std::convert::Infallible>(
                (
                    [(autumn_edge::FALLTHROUGH_SENTINEL, "missing_capability")],
                    "actionable message",
                )
                    .into_response(),
            )
        });
        let mut service = StripEdgeFallthroughSentinelLayer.layer(inner);
        let request = axum::extract::Request::builder()
            .uri("/")
            .body(axum::body::Body::empty())
            .expect("request");
        let response: axum::response::Response = service
            .ready()
            .await
            .expect("ready")
            .call(request)
            .await
            .expect("infallible");

        assert!(
            !response
                .headers()
                .contains_key(autumn_edge::FALLTHROUGH_SENTINEL)
        );
        let body = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("body");
        assert_eq!(body, b"actionable message".as_slice());
    }

