    // ── `#[static_get]` × multi-tenancy fails closed ───────────────────────
    //
    // `autumn build` and ISR send a bare synthetic request (path only: no `Host`, tenant
    // header, session or `Authorization`). Every tenancy `source` rejects a request that
    // lacks its signal instead of resolving a default tenant, and the non-2xx fails the
    // render, so no tenant's response lands in the `dist/` file every tenant shares.
    // Checked per source, so one that starts failing open is caught.
    #[tokio::test]
    async fn static_get_route_reading_tenant_fails_closed_for_every_tenancy_source() {
        async fn tenant_page(tenant: crate::tenancy::Tenant) -> String {
            tenant.0
        }

        for source in ["header", "subdomain", "session", "jwt"] {
            let mut config = AutumnConfig::default();
            config.tenancy.enabled = true;
            config.tenancy.source = source.to_owned();
            // A public path skips `tenancy_middleware`, so the request reaches the handler
            // and this exercises the `Tenant` extractor's own fallback. (`#[public]` would
            // not do: it only marks the route for the audit.)
            config.tenancy.public_paths = vec!["/storefront".to_owned()];

            let state = AppState::for_test();
            state.insert_extension(config.clone());

            let router = crate::router::try_build_router_inner(
                vec![Route {
                    method: http::Method::GET,
                    path: "/storefront",
                    handler: axum::routing::get(tenant_page),
                    name: "tenant_page",
                    api_doc: crate::openapi::ApiDoc {
                        method: "GET",
                        path: "/storefront",
                        operation_id: "tenant_page",
                        success_status: 200,
                        ..Default::default()
                    },
                    repository: None,
                    idempotency: crate::route::RouteIdempotency::Direct,
                    timeout: crate::route::RouteTimeout::Inherit,
                    criticality: crate::admission::Criticality::Default,
                    seo: crate::seo::SeoRouteDefaults::EMPTY,
                    api_version: None,
                    sunset_opt_out: false,
                    group: None,
                }],
                &config,
                state,
                crate::router::RouterContext {
                    exception_filters: Vec::new(),
                    scoped_groups: Vec::new(),
                    merge_routers: Vec::new(),
                    nest_routers: Vec::new(),
                    declared_routes: Vec::new(),
                    custom_layers: Vec::new(),
                    static_gate_layers: Vec::new(),
                    #[cfg(feature = "maud")]
                    error_page_renderer: None,
                    session_store: None,
                    #[cfg(feature = "openapi")]
                    openapi: None,
                    #[cfg(feature = "mcp")]
                    mcp: None,
                    #[cfg(feature = "webmcp")]
                    webmcp: None,
                },
            )
            .unwrap_or_else(|e| panic!("tenancy source {source:?}: router builds: {e}"));

            let tmp = tempfile::tempdir().expect("dist parent");
            let dist = tmp.path().join("dist");

            let result = crate::static_gen::render_static_routes(
                router,
                &[crate::static_gen::StaticRouteMeta {
                    path: "/storefront",
                    name: "tenant_page",
                    revalidate: None,
                    params_fn: None,
                    seo: crate::seo::SeoRouteDefaults::EMPTY,
                    content_type: None,
                }],
                &dist,
            )
            .await;

            assert!(
                result.is_err(),
                "tenancy source {source:?}: a #[static_get] route reading `Tenant` must fail \
                 the build rather than silently bake a default/missing tenant's response into \
                 a dist/ file every tenant's requests would then share"
            );
            assert!(
                !dist.join("storefront/index.html").exists(),
                "tenancy source {source:?}: no file must be written when tenant resolution fails"
            );
        }
    }

    // ── A failed rebuild leaves an existing static file in place ───────────
    //
    // `render_static_routes` stages into `dist.staging` and swaps it in only once every
    // route rendered; ISR's `regenerate_page` returns before writing on a non-2xx. A
    // failing render keeps serving the old file (stale-while-revalidate).
    //
    // Known limitation: a tenant-mismatched file (built with a different `[tenancy]`
    // config than the one serving) is never detected or expired; only a log line shows it.
    #[tokio::test]
    async fn failed_rebuild_leaves_preexisting_static_file_untouched() {
        async fn tenant_page(tenant: crate::tenancy::Tenant) -> String {
            tenant.0
        }

        let mut config = AutumnConfig::default();
        config.tenancy.enabled = true;
        config.tenancy.source = "header".to_owned();
        config.tenancy.public_paths = vec!["/storefront".to_owned()];

        let state = AppState::for_test();
        state.insert_extension(config.clone());

        let router = crate::router::try_build_router_inner(
            vec![Route {
                method: http::Method::GET,
                path: "/storefront",
                handler: axum::routing::get(tenant_page),
                name: "tenant_page",
                api_doc: crate::openapi::ApiDoc {
                    method: "GET",
                    path: "/storefront",
                    operation_id: "tenant_page",
                    success_status: 200,
                    ..Default::default()
                },
                repository: None,
                idempotency: crate::route::RouteIdempotency::Direct,
                timeout: crate::route::RouteTimeout::Inherit,
                criticality: crate::admission::Criticality::Default,
                seo: crate::seo::SeoRouteDefaults::EMPTY,
                api_version: None,
                sunset_opt_out: false,
                group: None,
            }],
            &config,
            state,
            crate::router::RouterContext {
                exception_filters: Vec::new(),
                scoped_groups: Vec::new(),
                merge_routers: Vec::new(),
                nest_routers: Vec::new(),
                declared_routes: Vec::new(),
                custom_layers: Vec::new(),
                static_gate_layers: Vec::new(),
                #[cfg(feature = "maud")]
                error_page_renderer: None,
                session_store: None,
                #[cfg(feature = "openapi")]
                openapi: None,
                #[cfg(feature = "mcp")]
                mcp: None,
                #[cfg(feature = "webmcp")]
                webmcp: None,
            },
        )
        .expect("router builds");

        let tmp = tempfile::tempdir().expect("dist parent");
        let dist = tmp.path().join("dist");

        // Seed `dist/` as if an earlier successful build had captured tenant A's response.
        std::fs::create_dir_all(dist.join("storefront")).expect("mkdir storefront");
        let sentinel = "tenant-a-sentinel-warden-2026-09-04";
        std::fs::write(dist.join("storefront/index.html"), sentinel).expect("seed stale file");
        let mut seed_routes = std::collections::HashMap::new();
        seed_routes.insert(
            "/storefront".to_owned(),
            crate::static_gen::ManifestEntry::new("storefront/index.html".to_owned()),
        );
        let manifest = crate::static_gen::StaticManifest::new(seed_routes);
        std::fs::write(
            dist.join("manifest.json"),
            serde_json::to_string(&manifest).expect("serialize manifest"),
        )
        .expect("write manifest");

        let result = crate::static_gen::render_static_routes(
            router,
            &[crate::static_gen::StaticRouteMeta {
                path: "/storefront",
                name: "tenant_page",
                revalidate: None,
                params_fn: None,
                seo: crate::seo::SeoRouteDefaults::EMPTY,
                content_type: None,
            }],
            &dist,
        )
        .await;

        assert!(
            result.is_err(),
            "the rebuild must still fail closed (tenant resolution rejects the headerless \
             synthetic request), same as the fresh-dist case above"
        );

        let surviving = std::fs::read_to_string(dist.join("storefront/index.html"))
            .expect("the pre-existing file must still be present after a failed rebuild");
        assert_eq!(
            surviving, sentinel,
            "a failed rebuild must not silently alter or remove a pre-existing static file. \
             This is Autumn's documented stale-while-revalidate/atomic-swap design working as \
             intended, but it also means a tenant-mismatched file that reached dist/ by some \
             other means (an operational build/serve config mismatch, not a code path in this \
             framework) is served indefinitely with no automatic invalidation — see \
             docs/security/2026-09-04-static-gen-tenancy-fails-closed/README.md"
        );
    }

    #[test]
